import { Component, OnInit } from '@angular/core';
import { ApiConfigService } from '../../core/services/api-config.service';

@Component({
  selector: 'app-parametres',
  templateUrl: './parametres.page.html'
})
export class ParametresPage implements OnInit {
  ip = '';
  port = '';
  currentApiUrl = '';

  constructor(private apiConfig: ApiConfigService) {}

  ngOnInit(): void {
    const config = this.apiConfig.config;
    this.ip = config.ip;
    this.port = config.port;
    this.updateCurrentUrl();
    this.apiConfig.configUpdates.subscribe(() => this.updateCurrentUrl());
  }

  onIpInput(event: any): void {
    this.ip = String(event.target.value ?? '');
  }

  onPortInput(event: any): void {
    this.port = String(event.target.value ?? '');
  }

  save(): void {
    if (!this.validate()) {
      return;
    }

    this.apiConfig.save(this.ip, this.port);
    this.updateCurrentUrl();
    alert('Configuration enregistrée avec succès.');
  }

  private validate(): boolean {
    const ip = this.ip.trim();
    const port = this.port.trim();

    if (!ip) {
      alert('L\'adresse IP est requise.');
      return false;
    }

    if (!port || isNaN(Number(port)) || Number(port) < 1 || Number(port) > 65535) {
      alert('Le port doit être un nombre compris entre 1 et 65535.');
      return false;
    }

    return true;
  }

  private updateCurrentUrl(): void {
    this.currentApiUrl = this.apiConfig.getBase();
  }
}
<div class="pg">
  <div class="pg-header">
    <div>
      <h1 class="pg-title">Paramètres</h1>
      <p class="pg-sub"></p>
    </div>
  </div>

  <div class="settings-list">
    <div class="settings-section">
      <div class="settings-section-title">Serveur API</div>

      <ion-list>
        <ion-item>
          <ion-label position="stacked">Adresse IP</ion-label>
          <ion-input
            type="text"
            placeholder="ex: 192.168.1.10"
            [value]="ip"
            (ionInput)="onIpInput($event)"
            autocomplete="off"
          ></ion-input>
        </ion-item>

        <ion-item>
          <ion-label position="stacked">Port</ion-label>
          <ion-input
            type="number"
            placeholder="ex: 5000"
            [value]="port"
            (ionInput)="onPortInput($event)"
            inputmode="numeric"
          ></ion-input>
        </ion-item>
      </ion-list>

      <div class="settings-actions">
        <button class="btn btn-primary" (click)="save()">Enregistrer</button>
      </div>
    </div>

    <div class="settings-section">
      <div class="settings-section-title">À propos</div>
      <div class="settings-item">
        <div class="settings-item-info">
          <div class="settings-item-label">Version</div>
          <div class="settings-item-sub">1.0.0</div>
        </div>
      </div>
      <div class="settings-item">
        <div class="settings-item-info">
          <div class="settings-item-label">URL API actuelle</div>
          <div class="settings-item-sub">{{ currentApiUrl }}</div>
        </div>
      </div>
    </div>
  </div>
</div>
